   1	//! Benchmark-tab callback wiring. The planning and aggregation live in
   2	//! `crate::bench` (pure, unit-tested), the running in `crate::bench::exec`; this
   3	//! file is the seam between them and `AppState`.
   4	//!
   5	//! Four things worth knowing before editing here.
   6	//!
   7	//! **The prompt is a FILE and this tab never holds it**. The workload card
   8	//! carries a PATH (settings.ini `BenchPromptFile`, defaulting to
   9	//! `config\bench-prompt-43k.txt`), Edit hands that file to the system's default
  10	//! text editor, and the text is read at Run. Three consequences live in this
  11	//! file: `refresh_prompt_info` is the only reader and caches its result
  12	//! `(path, mtime, len)`-gated, because it is called from every keystroke AND
  13	//! from the 5 s status tick (that tick is what makes an external edit show up
  14	//! with no callback to hang off); `plan_from_ui` fills the plan from that
  15	//! CACHE, which is fine for a preview and would not be for a measurement; and
  16	//! `on_bench_run` therefore re-reads the file itself before validating. Editing
  17	//! in a window of ours was the first design and was dropped: a Slint TextEdit
  18	//! is already sluggish at a few hundred KB (`log_window.rs` shows its tail as a
  19	//! list of rows for exactly that), and the prompts worth putting in a file are the
  20	//! long ones.
  21	//!
  22	//! **The selection is an ORDERED list of preset ids, kept Rust-side**
  23	//! (`State.bench_selection`), not a set derived from the row model. Order is
  24	//! meaning: position 1 is the baseline every ratio in the results table is
  25	//! measured against, so checking a box APPENDS and unchecking closes the gap.
  26	//! Every change rebuilds the whole row model, which is what keeps the rows'
  27	//! one-way `checked` bindings honest (the same contract as the GPU table's).
  28	//!
  29	//! **The synthetic mode stops llama-server itself**, through
  30	//! `gui::stop_server_async_with`, and never through `runstate::stop`: that path
  31	//! also saves the conversation snapshot when the user has asked for one, and it
  32	//! is what keeps the footer, the tray and the run-status generation counter in
  33	//! step. Killing the server from under them would make the next periodic tick
  34	//! report a deliberate stop as "llama-server is no longer running", in red. The
  35	//! server is NOT restarted afterwards: the run's closing status says it is down,
  36	//! and starting it again is the user's call.
  37	//!
  38	//! **The preview is built by the code that builds the real thing**
  39	//! (`bench::synthetic_argv` + `runstate::render_command_line`, or
  40	//! `bench::live_body`), never by a second formatter that could drift from it.
  41	//! Same rule, and the same reason, as the Server tab's Command Line card.
  42	
  43	use super::*;
  44	
  45	use std::path::Path;
  46	use std::time::SystemTime;
  47	
  48	use crate::bench::{self, exec, Mode, Plan};
  49	use crate::ini;
  50	
  51	/// The last read of the live prompt file, cached in `State`.
  52	///
  53	/// It exists so `refresh_prompt_info` is free to call from anywhere: from a
  54	/// keystroke in an unrelated workload field, and from the 5 s status tick that
  55	/// makes an external edit show up on its own. Both would otherwise re-read a
  56	/// file that can be megabytes. The cache is a display cache ONLY: the run
  57	/// re-reads the file itself, so a stale entry can never be what gets
  58	/// benchmarked.
  59	pub(super) struct PromptRead {
  60	    /// `(modified, len)`, so an edit made outside does too. `None` when the
  61	    /// file does not exist, which is itself a state worth noticing a change
  62	    /// from.
  63	    stamp: Option<(Option<SystemTime>, u64)>,
  64	    /// The normalized text, for the preview. Empty when the read failed.
  65	    text: String,
  66	}
  67	
  68	/// One row of the prompt list.
  69	pub(super) struct PromptEntry {
  70	    path: std::path::PathBuf,
  71	    on: bool,
  72	    /// One of the two the standard spec pins: always listed, never removed.
  73	    shipped: bool,
  74	    read: Option<PromptRead>,
  75	    /// The readout under the row.
  76	    info: String,
  77	}
  78	
  79	fn file_stamp(path: &Path) -> Option<(Option<SystemTime>, u64)> {
  80	    let meta = std::fs::metadata(path).ok()?;
  81	    Some((meta.modified().ok(), meta.len()))
  82	}
  83	
  84	/// Seed the prompt list once: the two shipped prompts, then the configured
  85	/// one when it is not one of them, ticked; the 43k one when nothing is.
  86	fn seed_prompt_list(state: &Rc<RefCell<State>>) {
  87	    if !state.borrow().bench_prompts.is_empty() {
  88	        return;
  89	    }
  90	    let configured = settings::load().bench_prompt_path();
  91	    let mut rows: Vec<PromptEntry> = bench::SHIPPED_PROMPTS
  92	        .iter()
  93	        .map(|(file, _)| paths::config_dir().join(file))
  94	        .map(|path| PromptEntry {
  95	            on: path == configured,
  96	            path,
  97	            shipped: true,
  98	            read: None,
  99	            info: String::new(),
 100	        })
 101	        .collect();
 102	    if !rows.iter().any(|r| r.on) {
 103	        rows.push(PromptEntry {
 104	            path: configured,
 105	            on: true,
 106	            shipped: false,
 107	            read: None,
 108	            info: String::new(),
 109	        });
 110	    }
 111	    state.borrow_mut().bench_prompts = rows;
 112	}
 113	
 114	/// The ticked prompts' paths, in list order.
 115	fn ticked_paths(state: &Rc<RefCell<State>>) -> Vec<std::path::PathBuf> {
 116	    state
 117	        .borrow()
 118	        .bench_prompts
 119	        .iter()
 120	        .filter(|r| r.on)
 121	        .map(|r| r.path.clone())
 122	        .collect()
 123	}
 124	
 125	/// Tick exactly `paths`, adding any that is not listed yet.
 126	fn tick_only(state: &Rc<RefCell<State>>, paths: &[std::path::PathBuf]) {
 127	    let mut st = state.borrow_mut();
 128	    for r in st.bench_prompts.iter_mut() {
 129	        r.on = paths.contains(&r.path);
 130	    }
 131	    for p in paths {
 132	        if !st.bench_prompts.iter().any(|r| &r.path == p) {
 133	            st.bench_prompts.push(PromptEntry {
 134	                path: p.clone(),
 135	                on: true,
 136	                shipped: false,
 137	                read: None,
 138	                info: String::new(),
 139	            });
 140	        }
 141	    }
 142	}
 143	
 144	/// Re-read every listed prompt whose file changed, and republish the rows.
 145	/// Returns whether any text changed, so a caller that has to rebuild the
 146	/// preview knows to.
 147	pub(super) fn refresh_prompt_info(app: &AppWindow, state: &Rc<RefCell<State>>) -> bool {
 148	    seed_prompt_list(state);
 149	    let mut changed = false;
 150	    {
 151	        let mut st = state.borrow_mut();
 152	        for r in st.bench_prompts.iter_mut() {
 153	            let stamp = file_stamp(&r.path);
 154	            if r.read.as_ref().is_some_and(|p| p.stamp == stamp) {
 155	                continue;
 156	            }
 157	            let (text, info) = match bench::load_prompt_file(&r.path) {
 158	                Ok(t) => {
 159	                    let summary = bench::prompt_summary(&t);
 160	                    (t, summary)
 161	                }
 162	                // The error is the readout: "cannot read ..." beside the row is
 163	                // the whole diagnosis, and Run reports the same sentence.
 164	                Err(e) => (String::new(), e),
 165	            };
 166	            r.info = info;
 167	            r.read = Some(PromptRead { stamp, text });
 168	            changed = true;
 169	        }
 170	    }
 171	    let rows: Vec<BenchPromptRow> = state
 172	        .borrow()
 173	        .bench_prompts
 174	        .iter()
 175	        .map(|r| BenchPromptRow {
 176	            path: SharedString::from(r.path.to_string_lossy().into_owned()),
 177	            name: SharedString::from(r.path.file_name().unwrap_or_default().to_string_lossy().into_owned()),
 178	            info: SharedString::from(r.info.clone()),
 179	            on: r.on,
 180	            shipped: r.shipped,
 181	        })
 182	        .collect();
 183	    app.global::<AppState>()
 184	        .set_bench_prompts(ModelRc::new(VecModel::from(rows)));
 185	    changed
 186	}
 187	
 188	/// Every ticked prompt read FRESH, for a run: not the display cache, since the
 189	/// point of a prompt in a file is that it can be edited while this window is
 190	/// open. An empty one is refused by name.
 191	fn read_ticked_prompts(state: &Rc<RefCell<State>>) -> Result<Vec<bench::spec::Prompt>, String> {
 192	    let mut out = Vec::new();
 193	    for path in ticked_paths(state) {
 194	        let text = bench::load_prompt_file(&path)?;
 195	        if text.trim().is_empty() {
 196	            return Err(format!("The live mode needs a prompt: {} is empty.", path.display()));
 197	        }
 198	        out.push((Some(path), text));
 199	    }
 200	    if out.is_empty() {
 201	        return Err("Tick at least one prompt.".into());
 202	    }
 203	    Ok(out)
 204	}
 205	
 206	/// Native file picker for the prompt, seeded at the current file. Blocks the UI
 207	/// thread for the same reason the Server tab's folder picker does: a native
 208	/// modal dialog is supposed to hold its owner (see `gui.rs`'s threading note).
 209	///
 210	/// Text files are the filter, "all files" the escape hatch: a prompt is plain
 211	/// text but nothing says it has to be named `.txt`.
 212	fn pick_prompt_file(start: &Path) -> Option<std::path::PathBuf> {
 213	    let mut dialog = rfd::FileDialog::new()
 214	        .set_title("Pick a prompt file")
 215	        .add_filter("Text files", &["txt", "md", "prompt"])
 216	        .add_filter("All files", &["*"]);
 217	    if let Some(parent) = start.parent().filter(|p| p.is_dir()) {
 218	        dialog = dialog.set_directory(parent);
 219	    }
 220	    if let Some(name) = start.file_name().and_then(|n| n.to_str()) {
 221	        dialog = dialog.set_file_name(name);
 222	    }
 223	    dialog.pick_file()
 224	}
 225	
 226	/// Persist the first ticked prompt into settings.ini (`BenchPromptFile`, what
 227	/// `bench sweep` reads with no --prompt-file), read-modify-write so this
 228	/// cannot wipe another key. Called when a run starts.
 229	fn persist_prompt_path(app: &AppWindow, path: &Path) {
 230	    // The default stays empty, so the setting never pins today's data folder.
 231	    let field = if path == paths::bench_prompt_file() {
 232	        String::new()
 233	    } else {
 234	        path.to_string_lossy().into_owned()
 235	    };
 236	    let mut cfg = settings::load();
 237	    if cfg.bench_prompt_file.trim() == field {
 238	        return;
 239	    }
 240	    cfg.bench_prompt_file = field;
 241	    if let Err(e) = settings::save(&cfg) {
 242	        // The only reachable failure is a path carrying ';' or '#', which the
 243	        // INI comment rule would truncate on reload. Say so: the run itself
 244	        // still works, it just will not be remembered.
 245	        set_status(app, format!("Prompt file not remembered: {e}"), true);
 246	    }
 247	}
 248	
 249	/// The benchmark database the field names, or the default when it is empty:
 250	/// what the Saved runs list reads. A run reads settings.ini instead
 251	/// (`db::work_path`), which is why Run persists the field first.
 252	fn configured_db_path(s: &AppState) -> std::path::PathBuf {
 253	    settings::Settings {
 254	        bench_db: s.get_bench_db().to_string(),
 255	        ..settings::Settings::default()
 256	    }
 257	    .bench_db_path()
 258	}
 259	
 260	/// Native file picker for the database, seeded at the current file. Picks an
 261	/// EXISTING file: a new database is a typed path, created by the first run.
 262	fn pick_db_file(start: &Path) -> Option<std::path::PathBuf> {
 263	    let mut dialog = rfd::FileDialog::new()
 264	        .set_title("Pick a benchmark database")
 265	        .add_filter("SQLite databases", &["db", "sqlite", "sqlite3"])
 266	        .add_filter("All files", &["*"]);
 267	    if let Some(parent) = start.parent().filter(|p| p.is_dir()) {
 268	        dialog = dialog.set_directory(parent);
 269	    }
 270	    dialog.pick_file()
 271	}
 272	
 273	/// Persist the database path into settings.ini, read-modify-write. Returns
 274	/// false (with the reason on the status line) when it cannot be saved: the
 275	/// only reachable failure is a `;`/`#` in the path, which would reload
 276	/// truncated, and a run must then not start, or it would land in the database
 277	/// settings.ini still names rather than the one on screen.
 278	fn persist_db_path(app: &AppWindow) -> bool {
 279	    let field = app.global::<AppState>().get_bench_db().trim().to_string();
 280	    let mut cfg = settings::load();
 281	    if cfg.bench_db.trim() == field {
 282	        return true;
 283	    }
 284	    cfg.bench_db = field;
 285	    match settings::save(&cfg) {
 286	        Ok(()) => true,
 287	        Err(e) => {
 288	            set_status(app, format!("Benchmark database not saved: {e}"), true);
 289	            false
 290	        }
 291	    }
 292	}
 293	
 294	/// Seed / re-seed everything the tab reads from disk: the preset rows, the list
 295	/// of past runs, and the derived preview. Part of the `reload_all_from_disk` hub
 296	/// (startup seed + Refresh/F5).
 297	pub(super) fn refresh(app: &AppWindow, state: &Rc<RefCell<State>>) {
 298	    let s = app.global::<AppState>();
 299	    // First seed only: leave a workload the user has edited alone across an F5.
 300	    // The prompt PATH is disk-backed (settings.ini) unlike the rest of the
 301	    // workload, and is seeded here for the same reason the others are: an F5
 302	    // must not throw away a path typed but not yet run. Its FILE is re-read on
 303	    // every refresh below, which is the half that matters.
 304	    if s.get_bench_reps().is_empty() {
 305	        // Both shipped prompts, so both rows of the list read a file.
 306	        bench::ensure_shipped_prompt_files();
 307	        // As stored, not resolved: empty stays empty (the default), so saving
 308	        // the field back never pins today's data folder into settings.ini.
 309	        s.set_bench_db(SharedString::from(settings::load().bench_db.trim()));
 310	        s.set_bench_temp(SharedString::from("0"));
 311	        s.set_bench_max_tokens(SharedString::from(bench::DEFAULT_MAX_TOKENS.to_string()));
 312	        s.set_bench_reps(SharedString::from(bench::DEFAULT_REPS.to_string()));
 313	        s.set_bench_prompt_lens(SharedString::from(bench::DEFAULT_PROMPT_LENS));
 314	        s.set_bench_depths(SharedString::from(bench::DEFAULT_DEPTHS));
 315	        s.set_bench_n_gen(SharedString::from(bench::DEFAULT_GEN.to_string()));
 316	        s.set_bench_spec_options(string_model(spec_options(state)));
 317	        let mut keys = vec!["none".to_string()];
 318	        keys.extend(bench::sweep::SWEEPABLE.iter().map(|(k, _)| k.to_string()));
 319	        s.set_bench_ab_keys(string_model(keys));
 320	        s.set_bench_spec(SharedString::from(SPEC_CUSTOM));
 321	    }
 322	    // A preset can be renamed or deleted under us; a selection naming one that
 323	    // is gone would fail the run's preflight, so prune it here instead.
 324	    let known: Vec<String> = presets::load_all().into_iter().map(|p| p.id).collect();
 325	    state
 326	        .borrow_mut()
 327	        .bench_selection
 328	        .retain(|id| known.contains(id));
 329	    // Before the rows: `refresh_rows` ends in the preview, which is built from
 330	    // the cached prompt text this fills in.
 331	    refresh_prompt_info(app, state);
 332	    refresh_rows(app, state);
 333	    refresh_runs(app);
 334	}
 335	
 336	/// Rebuild the preset row model from disk crossed with the selection, then
 337	/// re-derive everything downstream of it (the preview, the baseline).
 338	fn refresh_rows(app: &AppWindow, state: &Rc<RefCell<State>>) {
 339	    let s = app.global::<AppState>();
 340	    let selection = state.borrow().bench_selection.clone();
 341	    let rows: Vec<BenchPresetRow> = presets::load_all()
 342	        .into_iter()
 343	        .map(|p| {
 344	            let pos = selection.iter().position(|id| id == &p.id);
 345	            BenchPresetRow {
 346	                id: SharedString::from(p.id),
 347	                // The file's BASE NAME: the full path would elide to nothing,
 348	                // and what matters here is whether two rows are the same file.
 349	                model: SharedString::from(file_name(&p.model)),
 350	                selected: pos.is_some(),
 351	                order: pos.map_or(0, |i| i as i32 + 1),
 352	            }
 353	        })
 354	        .collect();
 355	    s.set_bench_presets(model(rows));
 356	    s.set_bench_selected_count(selection.len() as i32);
 357	    s.set_bench_baseline(SharedString::from(
 358	        selection.first().cloned().unwrap_or_default(),
 359	    ));
 360	    refresh_preview(app, state);
 361	}
 362	
 363	fn file_name(path: &str) -> String {
 364	    std::path::Path::new(path)
 365	        .file_name()
 366	        .map(|n| n.to_string_lossy().into_owned())
 367	        .unwrap_or_else(|| path.to_string())
 368	}
