 370	/// Rebuild the pasteable preview and the mode's caveat block.
 371	pub(super) fn refresh_preview(app: &AppWindow, state: &Rc<RefCell<State>>) {
 372	    let s = app.global::<AppState>();
 373	    let plan = plan_from_ui(app, state);
 374	    s.set_bench_caveats(SharedString::from(
 375	        bench::caveats(plan.mode)
 376	            .iter()
 377	            .map(|c| format!("- {c}"))
 378	            .collect::<Vec<_>>()
 379	            .join("\n"),
 380	    ));
 381	    // The preview is "exactly what Run will do", and Run will refuse.
 382	    let bad = invalid_numbers(&s, plan.mode);
 383	    if !bad.is_empty() {
 384	        s.set_bench_preview(SharedString::from(format!(
 385	            "Run will refuse: {}.",
 386	            bad.join("; ")
 387	        )));
 388	        return;
 389	    }
 390	
 391	    let cfg = server_cfg::load();
 392	    let all = presets::load_all();
 393	    let chosen: Vec<presets::Preset> = plan
 394	        .presets
 395	        .iter()
 396	        .filter_map(|id| all.iter().find(|p| &p.id == id).cloned())
 397	        .collect();
 398	    if chosen.is_empty() {
 399	        s.set_bench_preview(SharedString::from(
 400	            "Select one or more presets above to see what will run.",
 401	        ));
 402	        return;
 403	    }
 404	
 405	    let text = match plan.mode {
 406	        Mode::Synthetic => match paths::llama_bench_exe() {
 407	            Some(exe) => {
 408	                let env = runstate::env_vars(&cfg);
 409	                let sweeps = bench::synthetic_sweeps(&plan);
 410	                // One block per (preset, sweep): the prefill and decode halves
 411	                // are separate invocations, and the preview has to show that or
 412	                // it would misrepresent both the runtime and the test count.
 413	                let mut blocks = Vec::new();
 414	                for p in &chosen {
 415	                    for sweep in &sweeps {
 416	                        blocks.push(format!(
 417	                            "# {} / {}\n{}",
 418	                            p.id,
 419	                            sweep.name,
 420	                            runstate::render_command_line(
 421	                                &exe.to_string_lossy(),
 422	                                &bench::synthetic_argv(p, &cfg, &plan, sweep),
 423	                                &env,
 424	                            )
 425	                        ));
 426	                    }
 427	                }
 428	                blocks.join("\n\n")
 429	            }
 430	            None => format!(
 431	                "{} not found next to llama-server. Build llama.cpp first, \
 432	                 or reinstall: the installer stages it into bin\\.",
 433	                crate::paths::binary_name("llama-bench")
 434	            ),
 435	        },
 436	        Mode::Live => {
 437	            let port = u16::try_from(cfg.port_or_default())
 438	                .unwrap_or(crate::server_cfg::DEFAULT_PORT as u16);
 439	            let head = match steps_preview(&s, state, &plan.presets) {
 440	                Some(Ok(text)) => format!("{text}\n\nThe first request:\n"),
 441	                Some(Err(e)) => {
 442	                    s.set_bench_preview(SharedString::from(format!("Run will refuse: {}.", e.trim_end_matches('.'))));
 443	                    return;
 444	                }
 445	                None => String::new(),
 446	            };
 447	            let first = format!("{head}{}", bench::live_preview(port, &chosen[0].id, &plan));
 448	            if chosen.len() == 1 {
 449	                first
 450	            } else {
 451	                // The bodies differ in one field, so repeating them whole would
 452	                // bury that difference in noise.
 453	                let rest: Vec<&str> = chosen[1..].iter().map(|p| p.id.as_str()).collect();
 454	                format!(
 455	                    "{first}\n\nThen the same request for: {} (only \"model\" differs).",
 456	                    rest.join(", ")
 457	                )
 458	            }
 459	        }
 460	    };
 461	    s.set_bench_preview(SharedString::from(text));
 462	}
