 464	/// The campaigns in the database at `path`, newest first, with the readout
 465	/// under the Database field. A missing file is not an error: it is a machine
 466	/// that has never benched, or a new database the next run creates.
 467	fn saved_campaigns(path: &Path) -> (Vec<bench::db::CampaignRow>, String) {
 468	    if !path.is_file() {
 469	        return (
 470	            Vec::new(),
 471	            format!(
 472	                "{} (not there yet: the first finished run creates it)",
 473	                path.display()
 474	            ),
 475	        );
 476	    }
 477	    let read =
 478	        bench::db::open_ro(path).and_then(|c| bench::db::campaigns(&c).map_err(|e| e.to_string()));
 479	    match read {
 480	        Ok(runs) => {
 481	            let info = format!(
 482	                "{} ({} campaign{})",
 483	                path.display(),
 484	                runs.len(),
 485	                if runs.len() == 1 { "" } else { "s" }
 486	            );
 487	            (runs, info)
 488	        }
 489	        Err(e) => (Vec::new(), format!("cannot read: {e}")),
 490	    }
