 522	/// A campaign's table: every run's points under the run's label, in run
 523	/// order (a tab run's labels are its preset ids, a sweep's `key=value`).
 524	fn load_campaign(db: &Path, name: &str) -> Result<(Vec<bench::Point>, Vec<String>, bool), String> {
 525	    let conn = bench::db::open_ro(db)?;
 526	    let (runs, report) = bench::db::campaign_runs(&conn, name).map_err(|e| e.to_string())?;
 527	    if runs.is_empty() {
 528	        return Err(format!("no runs in campaign {name}"));
 529	    }
 530	    let mut points = Vec::new();
 531	    let mut order = Vec::new();
 532	    for (label, _tool, json) in &runs {
 533	        points.extend(bench::record::points_from_json(label, json));
 534	        order.push(label.clone());
 535	    }
 536	    Ok((points, order, report.is_some()))
 537	}
