 539	/// The integer fields THIS mode reads whose text is not a number the run takes,
 540	/// one status-line phrase each; empty when the tab can run. Asked before
 541	/// `plan_from_ui`, whose fallback would otherwise run a mistyped Repetitions as
 542	/// the default 3, or drop a mistyped entry from Depths, without a word: a
 543	/// benchmark of a different workload than the one on screen. The fields of the
 544	/// other mode are hidden, so they are not held against this one.
 545	fn invalid_numbers(s: &AppState, mode: Mode) -> Vec<String> {
 546	    let mut out = Vec::new();
 547	    // A spec fixes repetitions and the output cap: its fields are greyed out
 548	    // and not what runs.
 549	    if mode == Mode::Live && chosen_spec(s).is_some() && !s.get_bench_spec_override() {
 550	        return out;
 551	    }
 552	    out.extend(ini::int_problem(
 553	        "Repetitions",
 554	        s.get_bench_reps().as_str(),
 555	        &ini::INT_POSITIVE,
 556	    ));
 557	    match mode {
 558	        Mode::Live => out.extend(ini::int_problem(
 559	            "Max output tokens",
 560	            s.get_bench_max_tokens().as_str(),
 561	            &ini::INT_NON_NEGATIVE,
 562	        )),
 563	        Mode::Synthetic => {
 564	            out.extend(bench::int_list_problem(
 565	                "Prompt lengths",
 566	                s.get_bench_prompt_lens().as_str(),
 567	            ));
 568	            out.extend(ini::int_problem(
 569	                "Generate",
 570	                s.get_bench_n_gen().as_str(),
 571	                &ini::INT_NON_NEGATIVE,
 572	            ));
 573	            out.extend(bench::int_list_problem(
 574	                "Depths",
 575	                s.get_bench_depths().as_str(),
 576	            ));
 577	        }
 578	    }
 579	    out
 580	}
