 582	/// Read the whole tab into a `Plan`. Numbers ride as text (the same reason every
 583	/// other numeric field in this app does: a SpinBox edits itself on a stray
 584	/// scroll), so an unparseable field falls back to its default here; Run and the
 585	/// preview ask `invalid_numbers` first, so that fallback is never what runs.
 586	fn plan_from_ui(app: &AppWindow, state: &Rc<RefCell<State>>) -> Plan {
 587	    let s = app.global::<AppState>();
 588	    let int = |v: SharedString, fallback: i32| ini::parse_int(v.as_str()).unwrap_or(fallback);
 589	    let mode = Mode::from_str(s.get_bench_mode().as_str());
 590	    Plan {
 591	        mode,
 592	        presets: state.borrow().bench_selection.clone(),
 593	        reps: int(s.get_bench_reps(), bench::DEFAULT_REPS).max(1),
 594	        // The CACHED text, which is what the preview needs. `on_bench_run`
 595	        // re-reads the files into the plan it actually runs: the preview may
 596	        // be up to one 5 s tick behind the file, a benchmark may not be behind
 597	        // at all.
 598	        // The first ticked prompt's: what the preview shows.
 599	        prompt: state
 600	            .borrow()
 601	            .bench_prompts
 602	            .iter()
 603	            .find(|r| r.on)
 604	            .and_then(|r| r.read.as_ref())
 605	            .map(|p| p.text.clone())
 606	            .unwrap_or_default(),
 607	        prompt_file: Some(
 608	            ticked_paths(state)
 609	                .first()
 610	                .cloned()
 611	                .unwrap_or_else(paths::bench_prompt_file),
 612	        ),
 613	        // Checked = "leave the preset's own --temp alone", which is a third
 614	        // instruction and not a missing one, so it must send NO temperature
 615	        // rather than a number.
 616	        temp: if s.get_bench_temp_default() {
 617	            None
 618	        } else {
 619	            Some(ini::parse_float(s.get_bench_temp().as_str()).unwrap_or(0.0))
 620	        },
 621	        max_tokens: int(s.get_bench_max_tokens(), bench::DEFAULT_MAX_TOKENS),
 622	        concurrency: bench::Concurrency::from_str(s.get_bench_concurrency().as_str())
 623	            .unwrap_or_default(),
 624	        prompt_lens: bench::parse_int_list(s.get_bench_prompt_lens().as_str()),
 625	        depths: bench::parse_int_list(s.get_bench_depths().as_str()),
 626	        n_gen: int(s.get_bench_n_gen(), bench::DEFAULT_GEN),
 627	        // Only a named campaign or a question needs one: without either, the
 628	        // run is a campaign of its own named after its stamp, as before.
 629	        campaign: {
 630	            let name = s.get_bench_campaign().trim().to_string();
 631	            let question = s.get_bench_question().trim().to_string();
 632	            (!name.is_empty() || !question.is_empty()).then(|| bench::record::Campaign {
 633	                name: if name.is_empty() {
 634	                    bench::stamp(bench::now_secs())
 635	                } else {
 636	                    name
 637	                },
 638	                question,
 639	                label: None,
 640	            })
 641	        },
 642	        spec: None,
 643	    }
 644	}
