 653	/// The Spec combo moved: tick that spec's prompts (so the list shows what it
 654	/// runs, and Override starts from them) and drop Override.
 655	fn spec_changed(app: &AppWindow, state: &Rc<RefCell<State>>) {
 656	    let s = app.global::<AppState>();
 657	    if let Some(Ok(spec)) = chosen_spec(&s) {
 658	        let paths: Vec<std::path::PathBuf> = spec.prompts.iter().map(|(p, _)| p.clone()).collect();
 659	        for p in &paths {
 660	            bench::ensure_prompt_file(p);
 661	        }
 662	        tick_only(state, &paths);
 663	    }
 664	    s.set_bench_spec_override(false);
