 670	/// Write what the card describes as a spec file of the user's: the chosen
 671	/// spec with Override's changes, or for custom one pass of the Workload
 672	/// fields; the ticked prompts pinned by their digest. Named after the file
 673	/// (never `standard` or `custom`), Version 1. Returns the name.
 674	fn save_spec(app: &AppWindow, state: &Rc<RefCell<State>>, path: &Path) -> Result<String, String> {
 675	    let s = app.global::<AppState>();
 676	    let name = path
 677	        .file_stem()
 678	        .map(|n| n.to_string_lossy().into_owned())
 679	        .unwrap_or_default();
 680	    if name.is_empty() || name == "standard" || name == SPEC_CUSTOM {
 681	        return Err(format!(
 682	            "the file name names the spec, and `{name}` is not one of yours: pick another"
 683	        ));
 684	    }
 685	    let bad = invalid_numbers(&s, Mode::Live);
 686	    if !bad.is_empty() {
 687	        return Err(bad.join("; "));
 688	    }
 689	    let plan = Plan {
 690	        mode: Mode::Live,
 691	        ..plan_from_ui(app, state)
 692	    };
 693	    let pin = |prompts: Vec<bench::spec::Prompt>| -> Vec<(std::path::PathBuf, String)> {
 694	        prompts
 695	            .into_iter()
 696	            .filter_map(|(f, t)| f.map(|f| (f, bench::prompt_info(&t).sha256)))
 697	            .collect()
 698	    };
 699	    let mut spec = match chosen_spec(&s) {
 700	        Some(spec) => {
 701	            let mut spec = spec?;
 702	            let changed = overridden(&s, state);
 703	            if changed.contains(&"prompt") {
 704	                spec.prompts = pin(read_ticked_prompts(state)?);
 705	            }
 706	            let derive = derive_from_ui(&s, state, &plan, &[]);
 707	            spec.max_tokens = derive.max_tokens.unwrap_or(spec.max_tokens);
 708	            for p in spec.passes.iter_mut() {
 709	                p.temp = derive.temp.unwrap_or(p.temp);
 710	                p.reps = derive.reps.unwrap_or(p.reps);
 711	                p.concurrency = derive.concurrency.unwrap_or(p.concurrency);
 712	            }
 713	            spec
 714	        }
 715	        None => bench::spec::Spec {
 716	            name: String::new(),
 717	            version: String::new(),
 718	            sha256: String::new(),
 719	            prompts: pin(read_ticked_prompts(state)?),
 720	            max_tokens: plan.max_tokens,
 721	            passes: vec![bench::spec::Pass {
 722	                name: "main".into(),
 723	                temp: plan.temp,
 724	                reps: plan.reps,
 725	                concurrency: (s.get_bench_concurrency() != "all").then_some(plan.concurrency),
 726	                overrides: Vec::new(),
 727	            }],
 728	            published: false,
 729	        },
 730	    };
 731	    spec.name = name.clone();
 732	    spec.version = "1".into();
 733	    let text = bench::spec::to_ini(&spec, &paths::config_dir());
 734	    // What reads back is what was meant: a spec this tab cannot load again is
 735	    // not saved.
 736	    bench::spec::parse(&text, &paths::config_dir())?;
 737	    crate::ini::atomic_write(path, &text).map_err(|e| format!("cannot write {}: {e}", path.display()))?;
 738	    Ok(name)
 739	}
