 741	/// What Run starts: one plan, or several into one campaign (a spec, several
 742	/// prompts, or concurrency `all`), the same split as `bench sweep`.
 743	enum Job {
 744	    One(Box<Plan>),
 745	    Steps(Vec<exec::Step>, String),
 746	}
