 748	/// The Spec combo's first entry: no spec, the Workload fields as set.
 749	const SPEC_CUSTOM: &str = "custom";
 750	/// The combo's prefix for a spec file of the user's (loaded or saved).
 751	const SPEC_FILE: &str = "file: ";
 752	
 753	/// The Spec combo: custom, every published version of `standard`
 754	/// (`standard.versions`, newest first), then the user's spec files.
 755	fn spec_options(state: &Rc<RefCell<State>>) -> Vec<String> {
 756	    let mut out: Vec<String> = bench::spec::published_versions(bench::spec::STANDARD_VERSIONS)
 757	        .into_iter()
 758	        .map(|(v, _)| format!("standard v{v}"))
 759	        .collect();
 760	    out.reverse();
 761	    out.insert(0, SPEC_CUSTOM.into());
 762	    out.extend(
 763	        state
 764	            .borrow()
 765	            .bench_spec_files
 766	            .iter()
 767	            .map(|p| format!("{SPEC_FILE}{}", p.display())),
 768	    );
 769	    out
 770	}
