 772	/// The spec the combo names: None for custom.
 773	fn chosen_spec(s: &AppState) -> Option<Result<bench::spec::Spec, String>> {
 774	    let v = s.get_bench_spec();
 775	    if v.is_empty() || v == SPEC_CUSTOM {
 776	        return None;
 777	    }
 778	    Some(if let Some(n) = v.strip_prefix("standard v") {
 779	        bench::spec::standard_version(n)
 780	    } else if let Some(path) = v.strip_prefix(SPEC_FILE) {
 781	        bench::spec::load(path)
 782	    } else {
 783	        Err(format!("unknown spec {v}"))
 784	    })
 785	}
