 787	/// The Workload fields Override can take over besides the prompts, by the
 788	/// name `Derive::fields` records, with their values as the card shows them.
 789	fn workload_values(s: &AppState) -> [(&'static str, String); 4] {
 790	    [
 791	        (
 792	            "temp",
 793	            if s.get_bench_temp_default() {
 794	                "preset".into()
 795	            } else {
 796	                s.get_bench_temp().to_string()
 797	            },
 798	        ),
 799	        ("max-tokens", s.get_bench_max_tokens().to_string()),
 800	        ("concurrency", s.get_bench_concurrency().to_string()),
 801	        ("reps", s.get_bench_reps().to_string()),
 802	    ]
 803	}
 804	
 805	const BASE_SEP: char = '\u{1f}';
 806	
 807	/// What Override changed of the spec: `prompt` when the ticked prompts are not
 808	/// the spec's, then each field changed since the tick. None without a spec or
 809	/// the tick.
 810	fn overridden(s: &AppState, state: &Rc<RefCell<State>>) -> Vec<&'static str> {
 811	    let Some(Ok(spec)) = chosen_spec(s) else {
 812	        return Vec::new();
 813	    };
 814	    if !s.get_bench_spec_override() {
 815	        return Vec::new();
 816	    }
 817	    let mut out = Vec::new();
 818	    let mut ticked = ticked_paths(state);
 819	    let mut pinned: Vec<std::path::PathBuf> = spec.prompts.iter().map(|(p, _)| p.clone()).collect();
 820	    ticked.sort();
 821	    pinned.sort();
 822	    if ticked != pinned {
 823	        out.push("prompt");
 824	    }
 825	    let base = s.get_bench_override_base();
 826	    let base: Vec<&str> = base.split(BASE_SEP).collect();
 827	    out.extend(
 828	        workload_values(s)
 829	            .iter()
 830	            .enumerate()
 831	            .filter(|(i, (_, v))| base.get(*i) != Some(&v.as_str()))
 832	            .map(|(_, (f, _))| *f),
 833	    );
 834	    out
 835	}
