 837	/// The spec values Override replaces, from `plan` (`plan_from_ui`'s) and the
 838	/// ticked `prompts` read fresh.
 839	fn derive_from_ui(
 840	    s: &AppState,
 841	    state: &Rc<RefCell<State>>,
 842	    plan: &Plan,
 843	    prompts: &[bench::spec::Prompt],
 844	) -> bench::spec::Derive {
 845	    let changed = overridden(s, state);
 846	    let on = |f: &str| changed.contains(&f);
 847	    bench::spec::Derive {
 848	        prompt: on("prompt").then(|| prompts.to_vec()),
 849	        temp: on("temp").then_some(plan.temp),
 850	        max_tokens: on("max-tokens").then_some(plan.max_tokens),
 851	        reps: on("reps").then_some(plan.reps),
 852	        concurrency: on("concurrency")
 853	            .then(|| (s.get_bench_concurrency() != "all").then_some(plan.concurrency)),
 854	    }
 855	}
