 857	fn prompt_label(p: &bench::spec::Prompt) -> String {
 858	    p.0.as_ref()
 859	        .and_then(|f| f.file_name())
 860	        .map(|n| n.to_string_lossy().into_owned())
 861	        .unwrap_or_else(|| "prompt".into())
 862	}
