 864	/// The job the tab describes. `plan` is `plan_from_ui`'s; `prompts` the
 865	/// ticked ones read fresh (empty for a synthetic run, or a spec that keeps its
 866	/// own), the first already in `plan`.
 867	fn job_from_ui(
 868	    s: &AppState,
 869	    state: &Rc<RefCell<State>>,
 870	    plan: Plan,
 871	    prompts: Vec<bench::spec::Prompt>,
 872	) -> Result<Job, String> {
 873	    let named = plan.campaign.clone();
 874	    let into = |name: String, steps: Vec<exec::Step>| {
 875	        let question = named.as_ref().map(|c| c.question.clone()).unwrap_or_default();
 876	        let steps = steps
 877	            .into_iter()
 878	            .map(|st| exec::Step {
 879	                plan: Plan {
 880	                    campaign: Some(bench::record::Campaign {
 881	                        name: name.clone(),
 882	                        question: question.clone(),
 883	                        label: None,
 884	                    }),
 885	                    ..st.plan
 886	                },
 887	                ..st
 888	            })
 889	            .collect();
 890	        Job::Steps(steps, name)
 891	    };
 892	    let explicit = s.get_bench_campaign().trim().to_string();
 893	    let ab = ab_from_ui(s, &plan.presets)?;
 894	    let ab_key = ab.as_ref().map(|(k, _)| k.as_str());
 895	    let expand = |steps: Vec<exec::Step>| match &ab {
 896	        Some((k, vs)) => bench::spec::ab_expand(steps, k, vs),
 897	        None => steps,
 898	    };
 899	    if let Some(spec) = chosen_spec(s) {
 900	        if plan.presets.is_empty() {
 901	            return Err("select one or more presets".into());
 902	        }
 903	        let spec = spec?;
 904	        let derive = derive_from_ui(s, state, &plan, &prompts);
 905	        let steps = expand(bench::spec::tab_steps(&spec, &plan, &derive, ab_key)?);
 906	        let name = if explicit.is_empty() {
 907	            bench::spec::default_campaign(&spec)
 908	        } else {
 909	            explicit
 910	        };
 911	        return Ok(into(name, steps));
 912	    }
 913	    if plan.mode != Mode::Live {
 914	        if ab.is_none() {
 915	            return Ok(Job::One(Box::new(plan)));
 916	        }
 917	        let name = if explicit.is_empty() { bench::stamp(bench::now_secs()) } else { explicit };
 918	        let one = vec![exec::Step {
 919	            label: String::new(),
 920	            overrides: Vec::new(),
 921	            plan,
 922	        }];
 923	        return Ok(into(name, expand(one)));
 924	    }
 925	    let all = s.get_bench_concurrency() == "all";
 926	    let scenarios = if all {
 927	        common_scenarios(&plan.presets)?
 928	    } else {
 929	        vec![plan.concurrency]
 930	    };
 931	    if prompts.len() <= 1 && scenarios.len() == 1 && !all && ab.is_none() {
 932	        return Ok(Job::One(Box::new(plan)));
 933	    }
 934	    let mut steps = Vec::new();
 935	    for p in &prompts {
 936	        for c in &scenarios {
 937	            let mut label = Vec::new();
 938	            if prompts.len() > 1 {
 939	                label.push(prompt_label(p));
 940	            }
 941	            if all {
 942	                label.push(c.as_str().to_string());
 943	            }
 944	            steps.push(exec::Step {
 945	                label: label.join(" · "),
 946	                overrides: Vec::new(),
 947	                plan: Plan {
 948	                    prompt: p.1.clone(),
 949	                    prompt_file: p.0.clone(),
 950	                    concurrency: *c,
 951	                    ..plan.clone()
 952	                },
 953	            });
 954	        }
 955	    }
 956	    let name = if explicit.is_empty() {
 957	        bench::stamp(bench::now_secs())
 958	    } else {
 959	        explicit
 960	    };
 961	    Ok(into(name, expand(steps)))
 962	}
 963	
 964	/// The A/B key and its values, each checked against every selected preset.
 965	/// None for `none`.
 966	fn ab_from_ui(s: &AppState, presets: &[String]) -> Result<Option<(String, Vec<String>)>, String> {
 967	    let key = s.get_bench_ab_key().to_string();
 968	    if key.is_empty() || key == "none" {
 969	        return Ok(None);
 970	    }
 971	    let text = s.get_bench_ab_values();
 972	    if text.trim().is_empty() {
 973	        return Err(format!("A/B on {key}: type the values to compare"));
 974	    }
 975	    let values = bench::sweep::parse_values(text.as_str())?;
 976	    if values.len() < 2 {
 977	        return Err(format!("A/B on {key} needs two or more values"));
 978	    }
 979	    for p in presets {
 980	        bench::sweep::check_values(p, &key, &values)?;
 981	    }
 982	    Ok(Some((key, values)))
 983	}
