 999	/// The preview's head for a run of several steps: what each one is, without
1000	/// reading the prompts (a spec's are checked against their pins at Run).
1001	fn steps_preview(
1002	    s: &AppState,
1003	    state: &Rc<RefCell<State>>,
1004	    presets: &[String],
1005	) -> Option<Result<String, String>> {
1006	    let head = runs_preview(s, state, presets);
1007	    let ab = match ab_from_ui(s, presets) {
1008	        Ok(None) => return head,
1009	        Ok(Some((k, vs))) => format!(
1010	            "A/B on {k}: every step once per value ({}), written to the presets for it and put back after.",
1011	            vs.join(" | ")
1012	        ),
1013	        Err(e) => return Some(Err(e)),
1014	    };
1015	    Some(match head {
1016	        None => Ok(ab),
1017	        Some(Ok(h)) => Ok(format!("{ab}\n{h}")),
1018	        Some(Err(e)) => Err(e),
1019	    })
