1022	fn runs_preview(
1023	    s: &AppState,
1024	    state: &Rc<RefCell<State>>,
1025	    presets: &[String],
1026	) -> Option<Result<String, String>> {
1027	    let ticked: Vec<String> = ticked_paths(state).iter().map(|p| path_name(p)).collect();
1028	    if let Some(spec) = chosen_spec(s) {
1029	        return Some(spec.and_then(|spec| {
1030	            let scenarios = common_scenarios(presets)?;
1031	            let changed = overridden(s, state);
1032	            let cap = if changed.contains(&"max-tokens") {
1033	                s.get_bench_max_tokens().trim().parse::<i32>().unwrap_or(0)
1034	            } else {
1035	                spec.max_tokens
1036	            };
1037	            let mut lines = vec![format!(
1038	                "Spec {} v{}, every request at its rules (output cap {}):",
1039	                spec.name,
1040	                spec.version,
1041	                if cap > 0 { cap.to_string() } else { "none".into() }
1042	            )];
1043	            if !spec.published {
1044	                lines.push(format!(
1045	                    "A spec of yours, not a published version of standard: recorded as spec = custom, derived from {} v{}.",
1046	                    spec.name, spec.version
1047	                ));
1048	            }
1049	            if !changed.is_empty() {
1050	                lines.push(format!(
1051	                    "Override: {} from the Workload card in every step; recorded as spec = custom, derived from {} v{}.",
1052	                    changed.join(", "),
1053	                    spec.name,
1054	                    spec.version
1055	                ));
1056	            }
1057	            let ui = workload_values(s);
1058	            let ui_of = |f: &str| {
1059	                changed
1060	                    .contains(&f)
1061	                    .then(|| ui.iter().find(|(k, _)| *k == f).map(|(_, v)| v.clone()))
1062	                    .flatten()
1063	            };
1064	            let prompts: Vec<String> = if changed.contains(&"prompt") {
1065	                ticked.clone()
1066	            } else {
1067	                spec.prompts.iter().map(|(f, _)| path_name(f)).collect()
1068	            };
1069	            for name in &prompts {
1070	                for pass in &spec.passes {
1071	                    let cs: Vec<String> = match ui_of("concurrency") {
1072	                        Some(c) if c != "all" => vec![c],
1073	                        Some(_) => scenarios.iter().map(|c| c.as_str().to_string()).collect(),
1074	                        None => match pass.concurrency {
1075	                            Some(c) => vec![c.as_str().to_string()],
1076	                            None => scenarios.iter().map(|c| c.as_str().to_string()).collect(),
1077	                        },
1078	                    };
1079	                    let temp = ui_of("temp")
1080	                        .unwrap_or_else(|| pass.temp.map_or("preset".to_string(), |t| t.to_string()));
1081	                    let reps = ui_of("reps").unwrap_or_else(|| pass.reps.to_string());
1082	                    let over = if pass.overrides.is_empty() {
1083	                        String::new()
1084	                    } else {
1085	                        let o: Vec<String> =
1086	                            pass.overrides.iter().map(|(k, v)| format!("{k} = {v}")).collect();
1087	                        format!(", presets set {} (llama-server restarted)", o.join(", "))
1088	                    };
1089	                    lines.push(format!(
1090	                        "- {} · {name}: temp {temp}, {reps} reps, concurrency {}{over}",
1091	                        pass.name,
1092	                        cs.join(", ")
1093	                    ));
1094	                }
1095	            }
1096	            Ok(lines.join("\n"))
1097	        }));
1098	    }
1099	    if Mode::from_str(s.get_bench_mode().as_str()) != Mode::Live {
1100	        return None;
1101	    }
1102	    let all = s.get_bench_concurrency() == "all";
1103	    if ticked.len() <= 1 && !all {
1104	        return None;
1105	    }
1106	    Some((|| {
1107	        let mut parts = Vec::new();
1108	        if ticked.len() > 1 {
1109	            parts.push(format!("prompts {}", ticked.join(", ")));
1110	        }
1111	        if all {
1112	            let cs: Vec<&str> = common_scenarios(presets)?.iter().map(|c| c.as_str()).collect();
1113	            parts.push(format!("concurrency {}", cs.join(", ")));
1114	        }
1115	        Ok(format!("In turn, into one campaign: {}.", parts.join(" x ")))
1116	    })())
1117	}
