1136	/// Start the run: clear the table, flip the running flag, and hand the plan to a
1137	/// worker thread whose events come back through the event loop.
1138	fn start_run(app: &AppWindow, state: &Rc<RefCell<State>>, job: Job) {
1139	    let s = app.global::<AppState>();
1140	    s.set_bench_running(true);
1141	    s.set_bench_rows(model(Vec::<BenchResultRow>::new()));
1142	    s.set_bench_showing(SharedString::default());
1143	    s.set_bench_report_campaign(SharedString::default());
1144	    s.set_bench_progress(SharedString::from("Starting…"));
1145	    set_status(app, "Benchmark running…".into(), false);
1146	
1147	    // Held until the run is done; refused rather than waited for, so the
1148	    // window never hangs on a sweep running in a terminal.
1149	    let gpu = match bench::gpu_lock::try_acquire() {
1150	        Ok(g) => std::sync::Arc::new(std::sync::Mutex::new(Some(g))),
1151	        Err(e) => {
1152	            s.set_bench_running(false);
1153	            s.set_bench_progress(SharedString::default());
1154	            set_status(app, format!("Not run: {e}."), true);
1155	            return;
1156	        }
1157	    };
1158	    let (order, mode) = match &job {
1159	        Job::One(plan) => (plan.presets.clone(), plan.mode),
1160	        Job::Steps(steps, _) => (
1161	            steps.first().map(|s| s.plan.presets.clone()).unwrap_or_default(),
1162	            Mode::Live,
1163	        ),
1164	    };
1165	    let app_weak = app.as_weak();
1166	    let on_event = move |event: exec::Event| {
1167	        if matches!(event, exec::Event::Done(_)) {
1168	            gpu.lock().map(|mut g| g.take()).ok();
1169	        }
1170	        let app_weak = app_weak.clone();
1171	        let order = order.clone();
1172	        slint::invoke_from_event_loop(move || {
1173	            let Some(app) = app_weak.upgrade() else {
1174	                return;
1175	            };
1176	            let s = app.global::<AppState>();
1177	            match event {
1178	                exec::Event::Progress(text) => {
1179	                    s.set_bench_progress(SharedString::from(text));
1180	                }
1181	                exec::Event::Points(points) => apply_points(&app, &points, &order),
1182	                exec::Event::Done(result) => {
1183	                    s.set_bench_running(false);
1184	                    s.set_bench_progress(SharedString::default());
1185	                    match result {
1186	                        Ok(campaign) => {
1187	                            s.set_bench_report_campaign(SharedString::from(campaign.as_str()));
1188	                            let tail = if mode == Mode::Synthetic {
1189	                                " llama-server is still stopped; start it when you need it."
1190	                            } else {
1191	                                ""
1192	                            };
1193	                            set_status(
1194	                                &app,
1195	                                format!(
1196	                                    "Benchmark finished: campaign {campaign} in bench.db.{tail}"
1197	                                ),
1198	                                false,
1199	                            );
1200	                        }
1201	                        Err(e) => set_status(&app, format!("Benchmark: {e}"), true),
1202	                    }
1203	                    refresh_runs(&app);
1204	                }
1205	            }
1206	        })
1207	        .ok();
1208	    };
1209	    let handle = match job {
1210	        Job::One(plan) => exec::spawn(*plan, on_event),
1211	        Job::Steps(steps, campaign) => exec::spawn_steps(steps, campaign, on_event),
1212	    };
1213	    state.borrow_mut().bench_handle = Some(handle);
1214	}
