1216	/// `tray` is `None` only in the test seam (`gui::wire_tabs_for_tests`), which
1217	/// builds no tray; the sole thing it gates is the automatic llama-server stop a
1218	/// synthetic run needs, and in a test there is no server to stop.
1219	pub(super) fn wire(
1220	    app: &AppWindow,
1221	    state: &Rc<RefCell<State>>,
1222	    tray: Option<slint::Weak<AppTray>>,
1223	) {
1224	    {
1225	        let app_weak = app.as_weak();
1226	        let state = state.clone();
1227	        app.global::<AppState>().on_bench_mode_picked(move |value| {
1228	            let Some(app) = app_weak.upgrade() else {
1229	                return;
1230	            };
1231	            // The whole workload card is kept across the switch (each mode
1232	            // reads its own half), so this only re-derives what the mode
1233	            // decides: the preview and the caveat block.
1234	            app.global::<AppState>().set_bench_mode(value);
1235	            refresh_preview(&app, &state);
1236	        });
1237	    }
1238	    {
1239	        let app_weak = app.as_weak();
1240	        let state = state.clone();
1241	        app.global::<AppState>().on_bench_toggle_preset(move |id| {
1242	            let Some(app) = app_weak.upgrade() else {
1243	                return;
1244	            };
1245	            {
1246	                let mut st = state.borrow_mut();
1247	                let id = id.to_string();
1248	                match st.bench_selection.iter().position(|x| x == &id) {
1249	                    // Unchecking closes the gap, so the remaining rows keep a
1250	                    // contiguous 1..n order and the baseline stays the top one.
1251	                    Some(i) => {
1252	                        st.bench_selection.remove(i);
1253	                    }
1254	                    // Checking APPENDS: the order is the run order, and the
1255	                    // first is the baseline.
1256	                    None => st.bench_selection.push(id),
1257	                }
1258	            }
1259	            refresh_rows(&app, &state);
1260	        });
1261	    }
1262	    {
1263	        let app_weak = app.as_weak();
