1268	                // inside is what lets a keystroke in the Temperature field call
1269	                // this without re-reading a megabyte.
1270	                refresh_prompt_info(&app, &state);
1271	                refresh_preview(&app, &state);
1272	            }
1273	        });
1274	    }
1275	    {
