1293	            let Some(app) = app_weak.upgrade() else {
1294	                return;
1295	            };
1296	            let start = ticked_paths(&state)
1297	                .first()
1298	                .cloned()
1299	                .unwrap_or_else(paths::bench_prompt_file);
1300	            let Some(picked) = pick_prompt_file(&start) else {
1301	                return;
