1499	            // version of the text would be wrong in the one way nothing
1500	            // downstream could detect (the report's own digest would agree
1501	            // with itself). A spec brings its own prompts, read and checked
1502	            // against their pins when its steps are built, unless Override
1503	            // took the prompts over.
1504	            let s = app.global::<AppState>();
1505	            let spec_set = chosen_spec(&s).is_some() && !overridden(&s, &state).contains(&"prompt");
1506	            let mut prompts = Vec::new();
1507	            if plan.mode == Mode::Live && !spec_set {
1508	                match read_ticked_prompts(&state) {
1509	                    Ok(p) => prompts = p,
1510	                    Err(e) => {
1511	                        set_status(&app, e, true);
1512	                        return;
1513	                    }
1514	                }
1515	                plan.prompt_file = prompts[0].0.clone();
1516	                plan.prompt = prompts[0].1.clone();
1517	                if let Some(first) = plan.prompt_file.clone() {
1518	                    persist_prompt_path(&app, &first);
1519	                }
1520	            }
1521	            if let Some(problem) = bench::validate(&plan).filter(|_| !spec_set) {
1522	                set_status(&app, problem, true);
1523	                return;
1524	            }
1525	            let job = match job_from_ui(&s, &state, plan, prompts) {
1526	                Ok(job) => job,
1527	                Err(e) => {
1528	                    set_status(&app, format!("Not run: {e}."), true);
1529	                    return;
1530	                }
1531	            };
1532	            // The synthetic engine cannot share the GPU with llama-server: a
1533	            // second resident copy of the model spills into shared memory and
1534	            // reads as a backend regression rather than as a mistake. So stop
1535	            // it first, through the canonical path (which snapshots the
1536	            // conversation when that is enabled), and run only once it is gone.
1537	            let needs_stop = matches!(&job, Job::One(p) if p.mode == Mode::Synthetic)
1538	                && app.global::<AppState>().get_server_running();
1539	            if needs_stop {
1540	                let state = state.clone();
1541	                let after = move |app: &AppWindow| {
1542	                    start_run(app, &state, job);
1543	                };
1544	                match tray_weak.clone() {
1545	                    Some(tray) => {
1546	                        stop_server_async_with(app.as_weak(), tray, Some(Box::new(after)))
1547	                    }
1548	                    // No tray only in the test seam, where nothing is running.
1549	                    None => set_status(
1550	                        &app,
1551	                        "Stop llama-server before a synthetic benchmark.".into(),
1552	                        true,
1553	                    ),
1554	                }
1555	                return;
1556	            }
1557	            start_run(&app, &state, job);
1558	        });
1559	    }
1560	    {
1561	        let app_weak = app.as_weak();
1562	        app.global::<AppState>().on_bench_override_toggled(move || {
1563	            let Some(app) = app_weak.upgrade() else {
1564	                return;
1565	            };
1566	            let s = app.global::<AppState>();
1567	            let base = if s.get_bench_spec_override() {
1568	                let v: Vec<String> = workload_values(&s).into_iter().map(|(_, v)| v).collect();
1569	                v.join(&BASE_SEP.to_string())
1570	            } else {
1571	                String::new()
1572	            };
1573	            s.set_bench_override_base(SharedString::from(base));
1574	            s.invoke_bench_changed();
1575	        });
1576	    }
1577	    {
1578	        let state = state.clone();
1579	        app.global::<AppState>().on_bench_cancel(move || {
1580	            if let Some(h) = state.borrow().bench_handle.as_ref() {
1581	                h.cancel();
1582	            }
1583	        });
1584	    }
1585	    {
1586	        let app_weak = app.as_weak();
1587	        app.global::<AppState>().on_bench_run_picked(move |name| {
1588	            let Some(app) = app_weak.upgrade() else {
1589	                return;
1590	            };
1591	            let s = app.global::<AppState>();
1592	            match load_campaign(&configured_db_path(&s), name.as_str()) {
1593	                Ok((points, order, has_report)) => {
1594	                    s.set_bench_showing(name.clone());
1595	                    s.set_bench_baseline(SharedString::from(
1596	                        order.first().cloned().unwrap_or_default(),
1597	                    ));
1598	                    s.set_bench_report_campaign(if has_report {
1599	                        name.clone()
1600	                    } else {
1601	                        SharedString::default()
1602	                    });
1603	                    apply_points(&app, &points, &order);
1604	                    set_status(&app, format!("Showing campaign {name}."), false);
1605	                }
1606	                Err(e) => set_status(&app, format!("Cannot read that campaign: {e}"), true),
1607	            }
1608	        });
1609	    }
1610	    {
1611	        let app_weak = app.as_weak();
1612	        app.global::<AppState>().on_bench_open_report(move || {
1613	            let Some(app) = app_weak.upgrade() else {
1614	                return;
1615	            };
1616	            let s = app.global::<AppState>();
1617	            let name = s.get_bench_report_campaign();
1618	            if name.is_empty() {
1619	                return;
1620	            }
1621	            // The report lives in bench.db; the editor gets a copy in the temp
1622	            // directory, rewritten on every open so it never goes stale.
1623	            let report = bench::db::open_ro(&configured_db_path(&s)).and_then(|c| {
1624	                bench::db::campaign_runs(&c, name.as_str())
1625	                    .map_err(|e| e.to_string())
1626	                    .and_then(|(_, r)| r.ok_or_else(|| "no report".to_string()))
1627	            });
1628	            let path = std::env::temp_dir().join(format!("llama-cpp-config-{name}.md"));
1629	            match report.and_then(|r| std::fs::write(&path, r).map_err(|e| e.to_string())) {
1630	                // The default .md handler, as for the prompt file.
1631	                Ok(()) => {
1632	                    let _ = paths::open_in_desktop(&path);
1633	                }
1634	                Err(e) => set_status(&app, format!("Cannot open the report: {e}"), true),
1635	            }
1636	        });
1637	    }
1638	}

  1	//! Paths for the llama.cpp-framework configuration tool.
  2	//!
  3	//! Four jobs: (1) the user runtime tree, %LOCALAPPDATA%\llama.cpp\ on Windows
  4	//! (config\server.ini, config\presets.ini, config\bench-prompt-43k.txt,
  5	//! logs\llama-server.log) and ~/.local/share/llama.cpp elsewhere, where the
  6	//! config files live in ~/.config/llama.cpp instead (`config_dir`), overridable
  7	//! for tests via LLAMA_CPP_CONFIG_DATA_ROOT; (2) locating llama.cpp's binaries
  8	//! across the installer and dev layouts (`llama_bin`, with `llama_server_exe` /
  9	//! `llama_bench_exe` as its two callers; it also strips canonicalize()'s \\?\
 10	//! prefix so the path is shell-pasteable); (3) the ONE
 11	//! path outside that tree, OpenCode's user config (`opencode_user_config`,
 12	//! ~/.config/opencode/opencode.json), used by the Integrations tab; (4) locating
 13	//! the ROCm/HIP runtime (`rocm_bin_dir`) so `proc` can make ggml-hip.dll
 14	//! loadable in the llama-server children we spawn.
 15	
 16	use std::path::{Path, PathBuf};
 17	
 18	fn env_path(var: &str) -> Option<PathBuf> {
 19	    std::env::var_os(var).map(PathBuf::from)
 20	}
 21	
 22	pub(crate) fn home_dir() -> PathBuf {
 23	    // Under the e2e redirect the temp dir stands in for the whole profile:
 24	    // home-derived paths (e.g. `server_cfg::default_models_dir`, which save()
 25	    // CREATES on disk) must stay inside the temp tree, or a redirected test
 26	    // would silently touch (and mkdir under) the user's real home.
 27	    if let Some(p) = env_path("LLAMA_CPP_CONFIG_DATA_ROOT") {
 28	        return p;
 29	    }
 30	    #[cfg(windows)]
 31	    {
 32	        env_path("USERPROFILE").expect("USERPROFILE not set")
 33	    }
 34	    #[cfg(not(windows))]
 35	    {
 36	        env_path("HOME").expect("HOME not set")
 37	    }
 38	}
 39	
 40	/// `%LOCALAPPDATA%\llama.cpp` on Windows, `$HOME/.local/share/llama.cpp` elsewhere.
 41	///
 42	/// `LLAMA_CPP_CONFIG_DATA_ROOT` overrides the whole tree (plus
 43	/// `opencode_user_config` below AND `home_dir` above, so home-derived
 44	/// defaults land in the temp tree too). It exists for the e2e tests under
 45	/// `src/tests/`, which point config IO at a temp dir so they never touch the
 46	/// user's real data; it is NOT a supported end-user knob.
 47	pub fn data_root() -> PathBuf {
 48	    if let Some(p) = env_path("LLAMA_CPP_CONFIG_DATA_ROOT") {
 49	        return p.join("llama.cpp");
 50	    }
 51	    #[cfg(windows)]
 52	    {
 53	        env_path("LOCALAPPDATA")
 54	            .expect("LOCALAPPDATA not set on Windows")
 55	            .join("llama.cpp")
 56	    }
 57	    #[cfg(not(windows))]
 58	    {
 59	        home_dir().join(".local").join("share").join("llama.cpp")
 60	    }
 61	}
 62	
 63	/// `<data_root>\config` on Windows. On Linux `$XDG_CONFIG_HOME/llama.cpp`,
 64	/// i.e. `~/.config/llama.cpp` unless the variable names another ABSOLUTE path
 65	/// (the XDG spec says a relative one is to be ignored): per user, as
 66	/// `%LOCALAPPDATA%` is, and the directory llama.cpp itself reads a
 67	/// `config.ini` from (`common/arg.cpp`), which is not a name this tool writes.
 68	/// Only the config files live there: logs, bench runs and saved states stay
 69	/// under `data_root()`. Under the test override it is `<data_root>/config` on
 70	/// every OS, so the e2e tests never touch a real config.
 71	pub fn config_dir() -> PathBuf {
 72	    #[cfg(not(windows))]
 73	    if env_path("LLAMA_CPP_CONFIG_DATA_ROOT").is_none() {
 74	        let base = env_path("XDG_CONFIG_HOME")
 75	            .filter(|p| p.is_absolute())
 76	            .unwrap_or_else(|| home_dir().join(".config"));
 77	        return base.join("llama.cpp");
 78	    }
 79	    data_root().join("config")
 80	}
 81	
 82	pub fn server_ini() -> PathBuf {
 83	    config_dir().join("server.ini")
 84	}
 85	
 86	pub fn presets_ini() -> PathBuf {
 87	    config_dir().join("presets.ini")
 88	}
 89	
 90	/// The presets switched OFF: same INI format as `presets_ini()`, sections moved
 91	/// here verbatim by `presets::set_enabled`. A different EXTENSION on purpose:
 92	/// llama-server only ever reads the file `--models-preset` names, so a preset
 93	/// parked here is simply not offered, while a `*.ini` glob (the user's own, or a
 94	/// backup tool's) cannot mistake it for a live config.
 95	pub fn presets_disabled_ini() -> PathBuf {
 96	    config_dir().join("presets.ini.disabled")
 97	}
