 99	/// The configurator's OWN settings (the Settings tab; see `settings.rs`),
100	/// kept apart from server.ini, whose every key maps to a llama-server flag.
101	pub fn settings_ini() -> PathBuf {
102	    config_dir().join("settings.ini")
103	}
