105	/// The live benchmark's prompt, as a plain UTF-8 text file the user owns.
106	///
107	/// Under `config\` and not under `bench\` on purpose: `bench\` is output (bench.db),
108	/// this is input,
109	/// and it is edited like the other three files in `config\`. Under
110	/// %LOCALAPPDATA% and not next to the binaries because `bin\` lives in
111	/// `$PROGRAMFILES64\llama.cpp`: a prompt shipped there could not be saved
112	/// without elevation and would be overwritten by the next upgrade's `File`
113	/// directive. The framework's own default text seeds this file on first use
114	/// (`bench::ensure_prompt_file`), which is how it ships without being installed.
115	///
116	/// This is only the DEFAULT: settings.ini's `BenchPromptFile` can point the
117	/// Benchmark tab and the CLI at any other file (a 32k-token prompt for
118	/// measuring the regime a long conversation runs in, say).
119	pub fn bench_prompt_file() -> PathBuf {
120	    config_dir().join("bench-prompt-43k.txt")
121	}
122	
123	/// The llama-server log file. ONE home for the path: `runstate::start()`
124	/// writes it, the GUI's "no longer running" message points at it.
125	pub fn server_log() -> PathBuf {
126	    data_root().join("logs").join("llama-server.log")
127	}
128	
129	/// `%USERPROFILE%\.config\opencode\opencode.json` on Windows,
130	/// `$HOME/.config/opencode/opencode.json` elsewhere.
131	///
132	/// The test override redirects this too: the e2e tests exercise flows that read
133	/// (and could one day write) opencode.json, and must never touch the real one.
134	pub fn opencode_user_config() -> PathBuf {
135	    if let Some(p) = env_path("LLAMA_CPP_CONFIG_DATA_ROOT") {
136	        return p.join("opencode").join("opencode.json");
137	    }
138	    home_dir()
139	        .join(".config")
140	        .join("opencode")
141	        .join("opencode.json")
142	}
