144	/// The ROCm/HIP runtime dir on Windows (`…\AMD\ROCm\<ver>\bin`, home of
145	/// `amdhip64_*.dll` / `rocblas.dll`). AMD's HIP SDK installer sets the
146	/// machine-wide `HIP_PATH` env var but does NOT add this dir to the system
147	/// PATH, and ggml loads backends dynamically, silently dropping ggml-hip.dll
148	/// when its imports don't resolve, so HIP GPUs then enumerate as Vulkan-only.
149	/// `proc::prepend_rocm_path` feeds this to every llama-server child. It is what
150	/// a build from source runs on; an installed tree bundles the runtime next to
151	/// llama-server.exe, which precedes PATH, so this dir is then not consulted. Primary
152	/// signal is `HIP_PATH`; fallback scans `%ProgramFiles%\AMD\ROCm` for the
153	/// newest versioned install. `None` when no ROCm is found, and on non-Windows
154	/// (there the loader resolves the runtime without PATH).
155	pub fn rocm_bin_dir() -> Option<PathBuf> {
156	    #[cfg(windows)]
157	    {
158	        if let Some(hip) = env_path("HIP_PATH") {
159	            let bin = hip.join("bin");
160	            if bin.is_dir() {
161	                return Some(bin);
162	            }
163	        }
164	        let root = env_path("ProgramFiles")?.join("AMD").join("ROCm");
165	        let versions: Vec<String> = std::fs::read_dir(&root)
166	            .ok()?
167	            .flatten()
168	            .filter(|e| e.path().join("bin").is_dir())
169	            .filter_map(|e| e.file_name().into_string().ok())
170	            .collect();
171	        let newest = newest_version(&versions)?;
172	        Some(root.join(newest).join("bin"))
173	    }
174	    #[cfg(not(windows))]
175	    {
176	        None
177	    }
178	}
179	
180	/// The highest version-shaped name ("7.1", "6.4.2") in `names`, compared by
181	/// numeric components: a string sort would rank "7.1" above "10.0". Names
182	/// with any non-numeric component are ignored.
183	#[cfg_attr(not(windows), allow(dead_code))]
184	fn newest_version(names: &[String]) -> Option<&String> {
185	    fn key(name: &str) -> Option<Vec<u32>> {
186	        name.split('.').map(|c| c.parse().ok()).collect()
187	    }
188	    names
189	        .iter()
190	        .filter_map(|n| key(n).map(|k| (k, n)))
191	        .max_by(|a, b| a.0.cmp(&b.0))
192	        .map(|(_, n)| n)
193	}
194	
195	pub fn binary_name(stem: &str) -> String {
196	    if cfg!(windows) {
197	        format!("{stem}.exe")
198	    } else {
199	        stem.to_string()
200	    }
201	}
