203	/// Where llama-server lives. See [`llama_bin`] for the search order.
204	pub fn llama_server_exe() -> Option<PathBuf> {
205	    llama_bin("llama-server")
206	}
207	
208	/// Where `llama-bench` lives: same tree as llama-server, since the installer
209	/// stages every tool cmake installs into one `bin\` (it is not pruned like the
210	/// `test-*` harnesses are). The Benchmark tab's synthetic mode runs it.
211	pub fn llama_bench_exe() -> Option<PathBuf> {
212	    llama_bin("llama-bench")
213	}
214	
215	/// Locate one of llama.cpp's binaries by stem. Tries (in order):
216	/// 1. `<exe-dir>\<binary>`: installer layout
217	/// 2. `<exe-dir>\..\..\llama.cpp-cmake\bin\<binary>`: the build scripts'
218	///    layout (exe in `build\<os>\cargo-target\release`, `<os>` being
219	///    `windows` or `linux`)
220	/// 3. `<exe-dir>\..\..\build\<os>\llama.cpp-cmake\bin\<binary>`: a bare
221	///    `cargo build` at the workspace root (exe in `target\release`)
222	/// 4. `<exe-dir>\..\build\<os>\llama.cpp-cmake\bin\<binary>`: alt dev layout
223	pub fn llama_bin(stem: &str) -> Option<PathBuf> {
224	    // The per-OS directory the build scripts generate everything into.
225	    #[cfg(windows)]
226	    const BUILD_OS_DIR: &str = "windows";
227	    #[cfg(not(windows))]
228	    const BUILD_OS_DIR: &str = "linux";
229	
230	    let exe = std::env::current_exe().ok()?;
231	    let exe_dir = exe.parent()?;
232	    let name = binary_name(stem);
233	    let name = name.as_str();
234	    let candidates = [
235	        exe_dir.join(name),
236	        exe_dir
237	            .join("..")
238	            .join("..")
239	            .join("llama.cpp-cmake")
240	            .join("bin")
241	            .join(name),
242	        exe_dir
243	            .join("..")
244	            .join("..")
245	            .join("build")
246	            .join(BUILD_OS_DIR)
247	            .join("llama.cpp-cmake")
248	            .join("bin")
249	            .join(name),
250	        exe_dir
251	            .join("..")
252	            .join("build")
253	            .join(BUILD_OS_DIR)
254	            .join("llama.cpp-cmake")
255	            .join("bin")
256	            .join(name),
257	    ];
258	    for c in &candidates {
259	        if c.exists() {
260	            return Some(
261	                c.canonicalize()
262	                    .map(strip_extended_prefix)
263	                    .unwrap_or_else(|_| c.clone()),
264	            );
265	        }
266	    }
267	    None
268	}
269	
270	/// Drop the `\\?\` extended-length prefix Windows' `canonicalize` prepends:
271	/// the path is also *displayed* (the Command Line card renders it as the
272	/// pasteable exe line), and some shells reject the prefix. UNC results
273	/// (`\\?\UNC\…`) are left as-is: a bare strip would corrupt them.
274	fn strip_extended_prefix(p: PathBuf) -> PathBuf {
275	    #[cfg(windows)]
276	    {
277	        if let Some(rest) = p.to_str().and_then(|s| s.strip_prefix(r"\\?\")) {
278	            if !rest.starts_with("UNC") {
279	                return PathBuf::from(rest);
280	            }
281	        }
282	    }
283	    p
284	}
