286	/// Hand a file or folder to the desktop's default handler: `explorer` on
287	/// Windows, `xdg-open` elsewhere.
288	pub fn open_in_desktop(path: &Path) -> std::io::Result<std::process::Child> {
289	    let opener = if cfg!(windows) {
290	        "explorer"
291	    } else {
292	        "xdg-open"
293	    };
294	    std::process::Command::new(opener).arg(path).spawn()
295	}
296	
297	/// A Windows path literal as the path of the OS the tests run on: unchanged on
298	/// Windows; elsewhere the drive is dropped and `\` becomes `/`
299	/// (`C:\m\x.gguf` -> `/m/x.gguf`), because `std::path` only splits on the
300	/// host's separator. For the tests that take a file name, a stem or a parent
301	/// out of a path: written once, they then hold on both OSes.
302	#[cfg(test)]
303	pub fn os_path(win: &str) -> String {
304	    if cfg!(windows) {
305	        return win.to_string();
306	    }
307	    let rest = match win.as_bytes() {
308	        [d, b':', ..] if d.is_ascii_alphabetic() => &win[2..],
309	        _ => win,
310	    };
311	    rest.replace('\\', "/")
312	}
